// Package postgres is identity's Repo on the platform database (queries.sql, generated by sqlc).
package postgres

import (
	"context"
	"database/sql"
	"errors"
	"time"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/identity"
)

// Repo implements identity.Repo.
type Repo struct {
	q *Queries
}

var _ identity.Repo = (*Repo)(nil)

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{q: New(db)} }

// UserIDs are every user's id, oldest first.
func (r *Repo) UserIDs(ctx context.Context) ([]int64, error) {
	return r.q.UserIDs(ctx)
}

// EnsureUser inserts the user unless it exists, then reads it (one statement each; a race inserts once).
func (r *Repo) EnsureUser(ctx context.Context, name string, now time.Time) (identity.User, error) {
	if err := r.q.InsertUser(ctx, InsertUserParams{Name: name, CreatedAt: now}); err != nil {
		return identity.User{}, err
	}
	u, err := r.q.UserByName(ctx, name)
	if err != nil {
		return identity.User{}, err
	}
	return user(u), nil
}

// User reads a user by id.
func (r *Repo) User(ctx context.Context, id int64) (identity.User, error) {
	u, err := r.q.UserByID(ctx, id)
	if err != nil {
		return identity.User{}, err
	}
	return user(u), nil
}

// CreateSession stores s.
func (r *Repo) CreateSession(ctx context.Context, s identity.Session) error {
	return r.q.InsertSession(ctx, InsertSessionParams{
		TokenHash: s.TokenHash, UserID: s.UserID, Csrf: s.CSRF,
		CreatedAt: s.CreatedAt, ExpiresAt: s.ExpiresAt,
	})
}

// Session reads a session by its token hash.
func (r *Repo) Session(ctx context.Context, tokenHash string) (identity.Session, error) {
	s, err := r.q.SessionByHash(ctx, tokenHash)
	if errors.Is(err, sql.ErrNoRows) {
		return identity.Session{}, identity.ErrNoSession
	}
	if err != nil {
		return identity.Session{}, err
	}
	return identity.Session{TokenHash: s.TokenHash, UserID: s.UserID, CSRF: s.Csrf, CreatedAt: s.CreatedAt,
		ExpiresAt: s.ExpiresAt}, nil
}

// DeleteExpired removes the sessions that expired before now.
func (r *Repo) DeleteExpired(ctx context.Context, now time.Time) error {
	return r.q.DeleteSessionsExpiredBefore(ctx, now)
}

func user(u User) identity.User {
	return identity.User{ID: u.ID, Name: u.Name, CreatedAt: u.CreatedAt}
}
